"""Lua lexer."""

KEYWORDS = {
    "and", "break", "do", "else", "elseif", "end", "false", "for",
    "function", "goto", "if", "in", "local", "nil", "not", "or",
    "repeat", "return", "then", "true", "until", "while",
}

class LexError(Exception):
    def __init__(self, msg, line):
        super().__init__(msg)
        self.msg = msg
        self.line = line


class Token:
    __slots__ = ("type", "value", "line")
    def __init__(self, type, value, line):
        self.type = type
        self.value = value
        self.line = line
    def __repr__(self):
        return f"Token({self.type!r},{self.value!r},{self.line})"


class Lexer:
    def __init__(self, src, source_name="?"):
        self.src = src
        self.pos = 0
        self.line = 1
        self.source_name = source_name
        # Skip shebang line
        if src.startswith("#!"):
            nl = src.find("\n")
            if nl < 0:
                self.pos = len(src)
            else:
                self.pos = nl + 1
                self.line = 2

    def error(self, msg):
        raise LexError(msg, self.line)

    def peek(self, off=0):
        p = self.pos + off
        if p >= len(self.src):
            return ""
        return self.src[p]

    def advance(self):
        c = self.src[self.pos]
        self.pos += 1
        if c == "\n":
            self.line += 1
        return c

    def match(self, c):
        if self.peek() == c:
            self.advance()
            return True
        return False

    def skip_space_and_comments(self):
        while self.pos < len(self.src):
            c = self.peek()
            if c in " \t\r\n":
                self.advance()
            elif c == "-" and self.peek(1) == "-":
                # comment
                self.advance(); self.advance()
                # long comment?
                if self.peek() == "[":
                    saved = self.pos
                    sline = self.line
                    self.advance()
                    level = 0
                    while self.peek() == "=":
                        level += 1
                        self.advance()
                    if self.peek() == "[":
                        self.advance()
                        self._read_long_bracket_body(level, sline)
                        continue
                    # Not a long comment; fall back to short
                    self.pos = saved
                    self.line = sline
                # short comment
                while self.pos < len(self.src) and self.peek() != "\n":
                    self.advance()
            else:
                break

    def _read_long_bracket_body(self, level, start_line):
        # Opening already consumed. Handle initial newline
        if self.peek() == "\r":
            self.advance()
        if self.peek() == "\n":
            self.advance()
        start = self.pos
        while True:
            if self.pos >= len(self.src):
                self.line = start_line
                self.error("unterminated long bracket")
            c = self.peek()
            if c == "]":
                save = self.pos
                self.advance()
                cnt = 0
                while self.peek() == "=":
                    cnt += 1
                    self.advance()
                if cnt == level and self.peek() == "]":
                    end = save
                    self.advance()
                    return self.src[start:end]
            else:
                self.advance()

    def read_long_string(self, level, start_line):
        return self._read_long_bracket_body(level, start_line)

    def read_string(self, quote):
        start_line = self.line
        self.advance()  # consume opening quote
        out = []
        while True:
            if self.pos >= len(self.src):
                self.line = start_line
                self.error("unterminated string")
            c = self.peek()
            if c == quote:
                self.advance()
                return "".join(out)
            if c == "\n":
                self.error("unterminated string")
            if c == "\\":
                self.advance()
                e = self.peek()
                if e == "":
                    self.error("unterminated string")
                if e == "a": out.append("\a"); self.advance()
                elif e == "b": out.append("\b"); self.advance()
                elif e == "f": out.append("\f"); self.advance()
                elif e == "n": out.append("\n"); self.advance()
                elif e == "r": out.append("\r"); self.advance()
                elif e == "t": out.append("\t"); self.advance()
                elif e == "v": out.append("\v"); self.advance()
                elif e == "\\": out.append("\\"); self.advance()
                elif e == '"': out.append('"'); self.advance()
                elif e == "'": out.append("'"); self.advance()
                elif e == "\n": out.append("\n"); self.advance()
                elif e == "\r":
                    self.advance()
                    if self.peek() == "\n":
                        self.advance()
                    out.append("\n")
                elif e == "x":
                    self.advance()
                    h = ""
                    for _ in range(2):
                        if self.peek() in "0123456789abcdefABCDEF":
                            h += self.advance()
                        else:
                            break
                    if not h:
                        self.error("hexadecimal digit expected")
                    out.append(chr(int(h, 16)))
                elif e.isdigit():
                    d = ""
                    for _ in range(3):
                        if self.peek().isdigit():
                            d += self.advance()
                        else:
                            break
                    n = int(d)
                    if n > 255:
                        self.error("decimal escape too large")
                    out.append(chr(n))
                elif e == "z":
                    self.advance()
                    while self.peek() in " \t\r\n\v\f":
                        self.advance()
                else:
                    self.error(f"invalid escape sequence '\\{e}'")
            else:
                out.append(self.advance())

    def read_number(self):
        start = self.pos
        is_float = False
        is_hex = False
        if self.peek() == "0" and self.peek(1) in ("x", "X"):
            self.advance(); self.advance()
            is_hex = True
            while self.peek() in "0123456789abcdefABCDEF":
                self.advance()
            if self.peek() == ".":
                is_float = True
                self.advance()
                while self.peek() in "0123456789abcdefABCDEF":
                    self.advance()
            if self.peek() in ("p", "P"):
                is_float = True
                self.advance()
                if self.peek() in ("+", "-"):
                    self.advance()
                while self.peek().isdigit():
                    self.advance()
        else:
            while self.peek().isdigit():
                self.advance()
            if self.peek() == ".":
                is_float = True
                self.advance()
                while self.peek().isdigit():
                    self.advance()
            if self.peek() in ("e", "E"):
                is_float = True
                self.advance()
                if self.peek() in ("+", "-"):
                    self.advance()
                while self.peek().isdigit():
                    self.advance()
        s = self.src[start:self.pos]
        try:
            if is_hex:
                if is_float:
                    val = float.fromhex(s)
                else:
                    val = int(s, 16)
                    # treat large hex as 32-bit unsigned? no, keep as int
            else:
                if is_float:
                    val = float(s)
                else:
                    val = int(s)
        except ValueError:
            self.error(f"malformed number near '{s}'")
        return val

    def read_ident(self):
        start = self.pos
        while self.peek().isalnum() or self.peek() == "_":
            self.advance()
        return self.src[start:self.pos]

    def next(self):
        self.skip_space_and_comments()
        if self.pos >= len(self.src):
            return Token("EOF", None, self.line)
        line = self.line
        c = self.peek()
        if c.isalpha() or c == "_":
            ident = self.read_ident()
            if ident in KEYWORDS:
                return Token(ident, ident, line)
            return Token("NAME", ident, line)
        if c.isdigit() or (c == "." and self.peek(1).isdigit()):
            val = self.read_number()
            return Token("NUMBER", val, line)
        if c in ('"', "'"):
            s = self.read_string(c)
            return Token("STRING", s, line)
        if c == "[":
            # long string?
            saved = self.pos
            sline = self.line
            self.advance()
            level = 0
            while self.peek() == "=":
                level += 1
                self.advance()
            if self.peek() == "[":
                self.advance()
                s = self.read_long_string(level, sline)
                return Token("STRING", s, line)
            # restore
            self.pos = saved
            self.line = sline
            self.advance()
            return Token("[", "[", line)
        # Punctuation
        two = self.src[self.pos:self.pos+2]
        three = self.src[self.pos:self.pos+3]
        if three == "...":
            self.pos += 3; return Token("...", "...", line)
        if three == "..." :
            pass
        if two in ("==", "~=", "<=", ">=", "::", "..", "<<", ">>", "//"):
            self.pos += 2
            return Token(two, two, line)
        single = "+-*/%^#<>=(){}[];:,.&|~"
        if c in single:
            self.advance()
            return Token(c, c, line)
        self.error(f"unexpected symbol near '{c}'")


def tokenize(src, source_name="?"):
    lex = Lexer(src, source_name)
    toks = []
    while True:
        t = lex.next()
        toks.append(t)
        if t.type == "EOF":
            break
    return toks
