KEYWORDS = {
    "and", "break", "do", "else", "elseif", "end", "false", "for",
    "function", "goto", "if", "in", "local", "nil", "not", "or",
    "repeat", "return", "then", "true", "until", "while",
}

class LexError(Exception):
    def __init__(self, msg, line):
        super().__init__(msg)
        self.msg = msg
        self.line = line


class Token:
    __slots__ = ("type", "value", "line")
    def __init__(self, type, value, line):
        self.type = type
        self.value = value
        self.line = line
    def __repr__(self):
        return f"Token({self.type!r},{self.value!r},{self.line})"


class Lexer:
    def __init__(self, src, source_name="?"):
        self.src = src
        self.pos = 0
        self.line = 1
        self.source_name = source_name
        # Skip shebang line
        if src.startswith("#!"):
            nl = src.find("\n")
            if nl < 0:
                self.pos = len(src)
            else:
                self.pos = nl + 1
                self.line = 2

    def error(self, msg):
        raise LexError(msg, self.line)

    def peek(self, off=0):
        p = self.pos + off
        if p >= len(self.src):
            return ""
        return self.src[p]

    def advance(self):
        c = self.src[self.pos]
        self.pos += 1
        if c == "\n":
            self.line += 1
        return c

    def match(self, c):
        if self.peek() == c:
            self.advance()
            return True
        return False

    def skip_space_and_comments(self):
        while self.pos < len(self.src):
            c = self.peek()
            if c in " \t\r\n":
                self.advance()
            elif c == "-" and self.peek(1) == "-":
                # comment
                self.advance(); self.advance()
                # long comment?
                if self.peek() == "[":
                    saved = self.pos
                    sline = self.line
                    self.advance()
                    level = 0
                    while self.peek() == "=":
                        level += 1
                        self.advance()
                    if self.peek() == "[":
                        self.advance()
                        self._read_long_bracket_body(level, sline)
                        continue
                    # Not a long comment; fall back to short
                    self.pos = saved
                    self.line = sline
                # short comment
                while self.pos < len(self.src) and self.peek() != "\n":
                    self.advance()
            else:
                break

    def _read_long_bracket_body(self, level, start_line):
        # Opening already consumed. Handle initial newline
        if self.peek() == "\r":
            self.advance()
        if self.peek() == "\n":
            self.advance()
        start = self.pos
        while True:
            if self.pos >= len(self.src):
                self.line = start_line
                self.error("unterminated long bracket")
            c = self.peek()
            if c == "]":
                save = self.pos
                self.advance()
                cnt = 0
                while self.peek() == "=":
                    cnt += 1
                    self.advance()
                if cnt == level and self.peek() == "]":
                    end = save
                    self.advance()
                    return self.src[start:end]
            else:
                self.advance()

    def read_long_string(self, level, start_line):
        return self._read_long_bracket_body(level, start_line)

    def read_string(self, quote):
        start_line = self.line
        self.advance()  # consume opening quote
        out = []
        while True:
            if self.pos >= len(self.src):
                self.line = start_line
                self.error("unterminated string")
