                self.error("unterminated string")
            if c == "\\":
                self.advance()
                e = self.peek()
                if e == "":
                    self.error("unterminated string")
                if e == "a": out.append("\a"); self.advance()
                elif e == "b": out.append("\b"); self.advance()
                elif e == "f": out.append("\f"); self.advance()
                elif e == "n": out.append("\n"); self.advance()
                elif e == "r": out.append("\r"); self.advance()
                elif e == "t": out.append("\t"); self.advance()
                elif e == "v": out.append("\v"); self.advance()
                elif e == "\\": out.append("\\"); self.advance()
                elif e == '"': out.append('"'); self.advance()
                elif e == "'": out.append("'"); self.advance()
