        "*": (7, 7, "*"), "/": (7, 7, "/"), "%": (7, 7, "%"),
        "^": (10, 9, "^"),  # right-assoc
    }
    UNARY_PREC = 8

    def parse_expr(self):
        return self.parse_binop(0)

    def parse_binop(self, limit):
        t = self.peek()
        if t.type in ("-", "not", "#"):
            op_line = t.line
            op = self.advance().type
            rhs = self.parse_binop(self.UNARY_PREC)
            left = Node("unop", op_line, op, rhs)
        else:
            left = self.parse_simple()
        while True:
            t = self.peek()
            prec = self.BINOP_PREC.get(t.type)
            if prec is None:
                break
            left_prec, right_prec, op = prec
            if left_prec <= limit:
                break
            op_line = self.advance().line
            rhs = self.parse_binop(right_prec)
            left = Node("binop", op_line, op, left, rhs)
        return left

    def parse_simple(self):
        t = self.peek()
        if t.type == "NUMBER":
            self.advance()
            return Node("number", t.line, t.value)
        if t.type == "STRING":
            self.advance()
            return Node("string", t.line, t.value)
        if t.type == "true":
            self.advance(); return Node("bool", t.line, True)
        if t.type == "false":
            self.advance(); return Node("bool", t.line, False)
        if t.type == "nil":
            self.advance(); return Node("nil", t.line)
        if t.type == "...":
            self.advance(); return Node("vararg", t.line)
        if t.type == "{":
            return self.parse_table()
        if t.type == "function":
            line = self.advance().line
            return self.parse_funcbody(line, False)
        return self.parse_prefixexpr()

    def parse_prefixexpr(self):
        t = self.peek()
        if t.type == "(":
            self.advance()
            e = self.parse_expr()
            self.expect(")")
            expr = Node("paren", t.line, e)
        elif t.type == "NAME":
            self.advance()
            expr = Node("name", t.line, t.value)
        else:
            self.error(f"unexpected symbol near '{t.value}'")
        # suffixes
        while True:
            t = self.peek()
            if t.type == ".":
                self.advance()
                fld = self.expect("NAME")
                expr = Node("index", fld.line, expr, Node("string", fld.line, fld.value))
            elif t.type == "[":
                self.advance()
                idx = self.parse_expr()
                self.expect("]")
                expr = Node("index", t.line, expr, idx)
            elif t.type == ":":
                self.advance()
                mname = self.expect("NAME").value
                args = self.parse_call_args()
                expr = Node("mcall", t.line, expr, mname, args)
            elif t.type in ("(", "STRING", "{"):
                args = self.parse_call_args()
                expr = Node("call", t.line, expr, args)
            else:
                break
        return expr

    def parse_call_args(self):
        t = self.peek()
        if t.type == "(":
            self.advance()
            if self.check(")"):
                self.advance()
                return []
            args = self.parse_exprlist()
            self.expect(")")
            return args
        if t.type == "STRING":
            self.advance()
            return [Node("string", t.line, t.value)]
        if t.type == "{":
            return [self.parse_table()]
        self.error("function arguments expected")

    def parse_table(self):
        line = self.advance().line  # '{'
        fields = []  # list of (kind, key, value)
        while not self.check("}"):
            t = self.peek()
            if t.type == "[":
                self.advance()
                k = self.parse_expr()
                self.expect("]")
                self.expect("=")
                v = self.parse_expr()
                fields.append(("kv", k, v))
            elif t.type == "NAME" and self.peek(1).type == "=":
                name = self.advance().value
                self.advance()  # '='
                v = self.parse_expr()
                fields.append(("kv", Node("string", t.line, name), v))
            else:
                v = self.parse_expr()
                fields.append(("item", None, v))
            if self.match(",") or self.match(";"):
                continue
            break
        self.expect("}", "{")
        return Node("table", line, fields)


