"""Lua parser producing AST."""

from lexer import tokenize, Token, LexError


class ParseError(Exception):
    def __init__(self, msg, line):
        super().__init__(msg)
        self.msg = msg
        self.line = line


# AST node types are simple tuples: (type, ...children...)
# Use classes for clarity.

class Node:
    __slots__ = ("type", "line", "children")
    def __init__(self, type, line, *children):
        self.type = type
        self.line = line
        self.children = children
    def __repr__(self):
        return f"Node({self.type}, {self.children})"


class Parser:
    def __init__(self, src, source_name="?"):
        self.source_name = source_name
        try:
            self.tokens = tokenize(src, source_name)
        except LexError as e:
            raise ParseError(e.msg, e.line)
        self.pos = 0

    def peek(self, off=0):
        return self.tokens[self.pos + off]

    def advance(self):
        t = self.tokens[self.pos]
        self.pos += 1
        return t

    def check(self, type):
        return self.peek().type == type

    def match(self, *types):
        if self.peek().type in types:
            return self.advance()
        return None

    def expect(self, type, ctx=""):
        t = self.peek()
        if t.type != type:
            raise ParseError(f"'{type}' expected" + (f" (to close '{ctx}')" if ctx else ""), t.line)
        return self.advance()

    def error(self, msg, line=None):
        if line is None:
            line = self.peek().line
        raise ParseError(msg, line)

    # ---- Statements ----

    def parse_chunk(self):
        line = self.peek().line
        body = self.parse_block()
        if not self.check("EOF"):
            self.error("'<eof>' expected")
        return Node("chunk", line, body)

    def parse_block(self):
        line = self.peek().line
        stmts = []
        while True:
            t = self.peek()
            if t.type in ("EOF", "end", "else", "elseif", "until"):
                break
            if t.type == "return":
                self.advance()
                exprs = []
                if self.peek().type not in ("EOF", "end", "else", "elseif", "until", ";"):
                    exprs = self.parse_exprlist()
                self.match(";")
                stmts.append(Node("return", t.line, exprs))
                break
            s = self.parse_stmt()
            if s is not None:
                stmts.append(s)
        return Node("block", line, stmts)

    def parse_stmt(self):
        t = self.peek()
        tp = t.type
        if tp == ";":
            self.advance()
            return None
        if tp == "if":
            return self.parse_if()
        if tp == "while":
            return self.parse_while()
        if tp == "do":
            self.advance()
            body = self.parse_block()
            self.expect("end", "do")
            return Node("do", t.line, body)
        if tp == "for":
            return self.parse_for()
        if tp == "repeat":
            return self.parse_repeat()
        if tp == "function":
            return self.parse_function_stmt()
        if tp == "local":
            return self.parse_local()
        if tp == "break":
            self.advance()
            return Node("break", t.line)
        if tp == "::":
            self.advance()
            name = self.expect("NAME").value
            self.expect("::")
            return Node("label", t.line, name)
        if tp == "goto":
            self.advance()
            name = self.expect("NAME").value
            return Node("goto", t.line, name)
        # Expression statement: assignment or function call
        return self.parse_exprstmt()

    def parse_if(self):
        line = self.advance().line  # 'if'
        cond = self.parse_expr()
        self.expect("then")
        then_body = self.parse_block()
        elifs = []
        else_body = None
        while self.check("elseif"):
            eline = self.advance().line
            econd = self.parse_expr()
            self.expect("then")
            ebody = self.parse_block()
            elifs.append((econd, ebody, eline))
        if self.match("else"):
            else_body = self.parse_block()
        self.expect("end", "if")
        return Node("if", line, cond, then_body, elifs, else_body)

    def parse_while(self):
        line = self.advance().line
        cond = self.parse_expr()
        self.expect("do")
        body = self.parse_block()
        self.expect("end", "while")
        return Node("while", line, cond, body)

    def parse_repeat(self):
        line = self.advance().line
        body = self.parse_block()
        self.expect("until")
        cond = self.parse_expr()
        return Node("repeat", line, body, cond)

    def parse_for(self):
        line = self.advance().line
        name1 = self.expect("NAME").value
        if self.check("="):
            self.advance()
            start = self.parse_expr()
            self.expect(",")
            stop = self.parse_expr()
            step = None
            if self.match(","):
                step = self.parse_expr()
            self.expect("do")
            body = self.parse_block()
            self.expect("end", "for")
            return Node("fornum", line, name1, start, stop, step, body)
        # generic for
        names = [name1]
        while self.match(","):
            names.append(self.expect("NAME").value)
        self.expect("in")
        exprs = self.parse_exprlist()
        self.expect("do")
        body = self.parse_block()
        self.expect("end", "for")
        return Node("forin", line, names, exprs, body)

    def parse_function_stmt(self):
        line = self.advance().line
        # funcname ::= NAME {'.' NAME} [':' NAME]
        name_tok = self.expect("NAME")
        target = Node("name", name_tok.line, name_tok.value)
        while self.match("."):
            fld = self.expect("NAME")
            target = Node("index", fld.line, target, Node("string", fld.line, fld.value))
        is_method = False
        if self.match(":"):
            fld = self.expect("NAME")
            target = Node("index", fld.line, target, Node("string", fld.line, fld.value))
            is_method = True
        func = self.parse_funcbody(line, is_method)
        return Node("assign", line, [target], [func])

    def parse_local(self):
        line = self.advance().line
        if self.match("function"):
            name = self.expect("NAME").value
            func = self.parse_funcbody(line, False)
            return Node("localfunction", line, name, func)
        names = [self.expect("NAME").value]
        while self.match(","):
            names.append(self.expect("NAME").value)
        exprs = []
        if self.match("="):
            exprs = self.parse_exprlist()
        return Node("local", line, names, exprs)

    def parse_funcbody(self, line, is_method):
        self.expect("(")
        params = []
        vararg = False
        if is_method:
            params.append("self")
        if not self.check(")"):
            while True:
                if self.match("..."):
                    vararg = True
                    break
                nm = self.expect("NAME").value
                params.append(nm)
                if not self.match(","):
                    break
        self.expect(")")
        body = self.parse_block()
        self.expect("end", "function")
        return Node("function", line, params, vararg, body)

    def parse_exprstmt(self):
        line = self.peek().line
        first = self.parse_prefixexpr()
        if self.peek().type in ("=", ","):
            # assignment
            lhs = [first]
            while self.match(","):
                lhs.append(self.parse_prefixexpr())
            # validate lhs
            for n in lhs:
                if n.type not in ("name", "index"):
                    self.error("syntax error (bad assignment target)", line)
            self.expect("=")
            rhs = self.parse_exprlist()
            return Node("assign", line, lhs, rhs)
        # must be call
        if first.type != "call" and first.type != "mcall":
            self.error("syntax error")
        return Node("exprstmt", line, first)

    # ---- Expressions ----

    def parse_exprlist(self):
        exprs = [self.parse_expr()]
        while self.match(","):
            exprs.append(self.parse_expr())
