        if t.type == "{":
            return self.parse_table()
        if t.type == "function":
            line = self.advance().line
            return self.parse_funcbody(line, False)
        return self.parse_prefixexpr()

    def parse_prefixexpr(self):
        t = self.peek()
        if t.type == "(":
            self.advance()
            e = self.parse_expr()
            self.expect(")")
            expr = Node("paren", t.line, e)
        elif t.type == "NAME":
            self.advance()
            expr = Node("name", t.line, t.value)
        else:
