"""Lua value types."""

class LuaError(Exception):
    def __init__(self, value, level=1, traceback=None):
        super().__init__(str(value))
        self.value = value  # the error value (could be string, table, etc.)
        self.level = level
        self.traceback = traceback

class LuaTable:
    __slots__ = ("array", "hash", "metatable")
    def __init__(self):
        self.array = []  # 1-indexed elements; self.array[0] is index 1
        self.hash = {}
        self.metatable = None

    def get(self, key):
        if key is None:
            return None
        if isinstance(key, float):
            if key != key:  # NaN
                return None
            if key.is_integer():
                ik = int(key)
                if 1 <= ik <= len(self.array):
                    v = self.array[ik - 1]
                    return v
                return self.hash.get(ik) if self.hash else None
        elif isinstance(key, int) and not isinstance(key, bool):
            if 1 <= key <= len(self.array):
                return self.array[key - 1]
            return self.hash.get(key)
        return self.hash.get(key)

    def rawset(self, key, value):
        if key is None:
            raise LuaError("table index is nil")
        if isinstance(key, float):
            if key != key:
                raise LuaError("table index is NaN")
            if key.is_integer():
                key = int(key)
        if isinstance(key, int) and not isinstance(key, bool):
            if 1 <= key <= len(self.array):
                self.array[key - 1] = value
                if value is None and key == len(self.array):
                    # trim
                    while self.array and self.array[-1] is None:
                        self.array.pop()
                return
            if key == len(self.array) + 1 and value is not None:
                self.array.append(value)
                # migrate from hash
                nxt = len(self.array) + 1
                while nxt in self.hash:
                    self.array.append(self.hash.pop(nxt))
                    nxt += 1
                return
        if value is None:
            self.hash.pop(key, None)
        else:
            self.hash[key] = value

    def length(self):
        # Lua length - returns a border
        return len(self.array)

    def iter_pairs(self):
        # Yield (key, value) for all set entries
        for i, v in enumerate(self.array, 1):
            if v is not None:
                yield (i, v)
        for k, v in self.hash.items():
            if v is not None:
                yield (k, v)


class LuaFunction:
    __slots__ = ("params", "is_vararg", "body", "env", "name")
    def __init__(self, params, is_vararg, body, env, name=None):
        self.params = params
        self.is_vararg = is_vararg
        self.body = body
        self.env = env
        self.name = name


class BuiltinFunction:
    __slots__ = ("fn", "name")
    def __init__(self, fn, name=None):
        self.fn = fn
        self.name = name or getattr(fn, "__name__", "?")
    def __call__(self, *args):
        return self.fn(*args)


def lua_type(v):
    if v is None:
        return "nil"
    if isinstance(v, bool):
        return "boolean"
    if isinstance(v, (int, float)):
        return "number"
    if isinstance(v, str):
        return "string"
    if isinstance(v, LuaTable):
        return "table"
    if isinstance(v, (LuaFunction, BuiltinFunction)):
        return "function"
    return "userdata"


def is_truthy(v):
    if v is None or v is False:
        return False
    return True


def lua_tostring(v):
    """Default tostring for builtins (no metatable lookup)."""
    if v is None:
        return "nil"
    if v is True:
        return "true"
    if v is False:
        return "false"
    if isinstance(v, float):
        if v != v:
            return "nan"
        if v == float("inf"):
            return "inf"
        if v == float("-inf"):
            return "-inf"
        if v.is_integer() and abs(v) < 1e16:
            # LuaJIT prints integer floats with ".0"? Actually no, it doesn't have integers
            # But uses %.14g which for 1e10 gives "10000000000"
            pass
        s = ("%.14g" % v)
        return s
    if isinstance(v, int):
        return str(v)
    if isinstance(v, str):
        return v
    if isinstance(v, LuaTable):
        return f"table: 0x{id(v):014x}"
    if isinstance(v, (LuaFunction, BuiltinFunction)):
        return f"function: 0x{id(v):014x}"
    return str(v)


def lua_tonumber(v, base=None):
    if base is not None:
        if not isinstance(v, str):
            return None
        try:
            b = int(base)
            s = v.strip()
            return int(s, b)
        except Exception:
            return None
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return v
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        try:
            if s.startswith("0x") or s.startswith("0X") or s.startswith("-0x") or s.startswith("-0X") or s.startswith("+0x") or s.startswith("+0X"):
                sign = 1
                t = s
                if t[0] in "+-":
                    if t[0] == "-":
                        sign = -1
                    t = t[1:]
                # hex: could have fractional?
                return sign * int(t, 16)
            # Try int first
            try:
                return int(s)
            except ValueError:
                return float(s)
        except (ValueError, OverflowError):
            return None
    return None
