"""Lua interpreter (tree-walking)."""

import math
import sys
from values import (
    LuaError, LuaTable, LuaFunction, BuiltinFunction,
    lua_type, is_truthy, lua_tostring, lua_tonumber,
)


class Environment:
    __slots__ = ("vars", "parent")
    def __init__(self, parent=None):
        self.vars = {}
        self.parent = parent

    def get_local(self, name):
        env = self
        while env is not None:
            if name in env.vars:
                return True, env.vars[name]
            env = env.parent
        return False, None

    def set_local(self, name, value):
        """Set existing local. Returns True if found, else False."""
        env = self
        while env is not None:
            if name in env.vars:
                env.vars[name] = value
                return True
            env = env.parent
        return False

    def declare_local(self, name, value):
        self.vars[name] = value


class BreakException(Exception):
    pass

class ContinueException(Exception):
    pass

class GotoException(Exception):
    def __init__(self, label):
        self.label = label

class ReturnException(Exception):
    def __init__(self, values):
        self.values = values


class Interpreter:
    def __init__(self, globals_table, source_name="?"):
        self.globals = globals_table
        self.source_name = source_name
        self.call_stack = []  # list of (name, line)

    def arith(self, op, a, b, line):
        na = lua_tonumber(a) if not isinstance(a, bool) else None
        nb = lua_tonumber(b) if not isinstance(b, bool) else None
        if na is None or nb is None:
            which = "arithmetic"
            raise LuaError(self._rt_err(f"attempt to perform arithmetic on a {lua_type(a if na is None else b)} value", line))
        if op == "+": return na + nb
        if op == "-": return na - nb
        if op == "*": return na * nb
        if op == "/":
            if nb == 0:
                if na == 0:
                    return float("nan")
                if na > 0:
                    return float("inf")
                return float("-inf")
            return na / nb
        if op == "%":
            if nb == 0:
                return float("nan")
            # Lua modulo: a - floor(a/b)*b
            return na - math.floor(na / nb) * nb
        if op == "^":
            return math.pow(na, nb)
        raise LuaError(f"bad arith op {op}")

    def _rt_err(self, msg, line):
        return f"{self.source_name}:{line}: {msg}"

    def compare(self, op, a, b, line):
        if op in ("==", "~="):
            eq = self.raw_equal(a, b)
            # TODO: metamethods __eq
            return eq if op == "==" else not eq
        # <, <=, >, >= - only for numbers/strings of same type
        if isinstance(a, bool) or isinstance(b, bool):
            raise LuaError(self._rt_err(f"attempt to compare {lua_type(a)} with {lua_type(b)}", line))
        if isinstance(a, (int, float)) and isinstance(b, (int, float)):
            if op == "<": return a < b
            if op == "<=": return a <= b
            if op == ">": return a > b
            if op == ">=": return a >= b
        if isinstance(a, str) and isinstance(b, str):
            if op == "<": return a < b
            if op == "<=": return a <= b
            if op == ">": return a > b
            if op == ">=": return a >= b
        raise LuaError(self._rt_err(f"attempt to compare {lua_type(a)} with {lua_type(b)}", line))

    def raw_equal(self, a, b):
        if a is None and b is None:
            return True
        if a is None or b is None:
            return False
        if isinstance(a, bool) or isinstance(b, bool):
            if isinstance(a, bool) and isinstance(b, bool):
                return a == b
            return False
        # numeric comparison across int/float
        if isinstance(a, (int, float)) and isinstance(b, (int, float)):
            return a == b
        if type(a) != type(b):
            return False
        return a is b or a == b

    def concat(self, a, b, line):
        def is_cat(v):
            return isinstance(v, (str, int, float)) and not isinstance(v, bool)
        if not is_cat(a):
            raise LuaError(self._rt_err(f"attempt to concatenate a {lua_type(a)} value", line))
        if not is_cat(b):
            raise LuaError(self._rt_err(f"attempt to concatenate a {lua_type(b)} value", line))
        return lua_tostring(a) + lua_tostring(b)

    def length(self, v, line):
        if isinstance(v, str):
            return len(v.encode("utf-8")) if any(ord(c) > 127 for c in v) else len(v)
        if isinstance(v, LuaTable):
            if v.metatable is not None:
                mm = v.metatable.get("__len")
                if mm is not None:
                    r = self.call(mm, [v], line)
                    return r[0] if r else None
            return v.length()
        raise LuaError(self._rt_err(f"attempt to get length of a {lua_type(v)} value", line))

    def table_get(self, t, key, line):
        if isinstance(t, LuaTable):
            v = t.get(key)
            if v is not None:
                return v
            if t.metatable is not None:
                idx = t.metatable.get("__index")
                if idx is not None:
                    if isinstance(idx, LuaTable):
                        return self.table_get(idx, key, line)
                    r = self.call(idx, [t, key], line)
                    return r[0] if r else None
            return None
        if isinstance(t, str):
            # string metatable: uses global 'string' table as index
            s_tab = self.globals.get("string")
            if isinstance(s_tab, LuaTable):
                return s_tab.get(key)
            return None
        if t is None:
            raise LuaError(self._rt_err(f"attempt to index a nil value", line))
        raise LuaError(self._rt_err(f"attempt to index a {lua_type(t)} value", line))

    def table_set(self, t, key, value, line):
        if isinstance(t, LuaTable):
            existing = t.get(key)
            if existing is None and t.metatable is not None:
                newidx = t.metatable.get("__newindex")
                if newidx is not None:
                    if isinstance(newidx, LuaTable):
                        self.table_set(newidx, key, value, line)
                        return
                    self.call(newidx, [t, key, value], line)
                    return
            t.rawset(key, value)
            return
        if t is None:
            raise LuaError(self._rt_err(f"attempt to index a nil value", line))
        raise LuaError(self._rt_err(f"attempt to index a {lua_type(t)} value", line))

    # ---- Execution ----

    def exec_chunk(self, ast, env, varargs=None):
        # chunk = Node("chunk", line, block)
        try:
            self.exec_block(ast.children[0], env, varargs)
        except ReturnException as r:
            return r.values
        return []

    def exec_block(self, block_node, env, varargs=None):
        stmts = block_node.children[0]
        i = 0
        while i < len(stmts):
            s = stmts[i]
            try:
                self.exec_stmt(s, env, varargs)
                i += 1
            except GotoException as g:
                # find label in current block
                found = None
                for j, st in enumerate(stmts):
                    if st.type == "label" and st.children[0] == g.label:
                        found = j
                        break
                if found is None:
                    raise
                i = found + 1

    def exec_stmt(self, node, env, varargs):
        t = node.type
        if t == "assign":
            lhs_nodes, rhs_nodes = node.children
            values = self.eval_exprlist(rhs_nodes, env, varargs, len(lhs_nodes))
            # Evaluate LHS targets first (lua evaluates lhs before rhs but for simplicity we do this order)
            for i, tgt in enumerate(lhs_nodes):
                val = values[i] if i < len(values) else None
                self.assign_target(tgt, val, env, varargs)
        elif t == "local":
            names, exprs = node.children
            vals = self.eval_exprlist(exprs, env, varargs, len(names)) if exprs else []
            for i, n in enumerate(names):
                env.declare_local(n, vals[i] if i < len(vals) else None)
        elif t == "localfunction":
            name, func_node = node.children
            env.declare_local(name, None)  # allow recursion
            fn = self.eval_expr(func_node, env, varargs)
            if isinstance(fn, LuaFunction):
                fn.name = name
            env.vars[name] = fn
        elif t == "exprstmt":
            self.eval_expr(node.children[0], env, varargs)
        elif t == "if":
            cond, then_body, elifs, else_body = node.children
            if is_truthy(self.eval_expr(cond, env, varargs)):
                self.exec_block(then_body, Environment(env), varargs)
            else:
                matched = False
                for econd, ebody, _el in elifs:
                    if is_truthy(self.eval_expr(econd, env, varargs)):
                        self.exec_block(ebody, Environment(env), varargs)
                        matched = True
                        break
                if not matched and else_body is not None:
                    self.exec_block(else_body, Environment(env), varargs)
