                if mm is not None:
                    r = self.call(mm, [v], line)
                    return r[0] if r else None
            return v.length()
        raise LuaError(self._rt_err(f"attempt to get length of a {lua_type(v)} value", line))

    def table_get(self, t, key, line):
        if isinstance(t, LuaTable):
            v = t.get(key)
            if v is not None:
                return v
            if t.metatable is not None:
                idx = t.metatable.get("__index")
                if idx is not None:
                    if isinstance(idx, LuaTable):
                        return self.table_get(idx, key, line)
                    r = self.call(idx, [t, key], line)
                    return r[0] if r else None
            return None
        if isinstance(t, str):
            # string metatable: uses global 'string' table as index
            s_tab = self.globals.get("string")
            if isinstance(s_tab, LuaTable):
                return s_tab.get(key)
            return None
        if t is None:
            raise LuaError(self._rt_err(f"attempt to index a nil value", line))
        raise LuaError(self._rt_err(f"attempt to index a {lua_type(t)} value", line))

    def table_set(self, t, key, value, line):
        if isinstance(t, LuaTable):
            existing = t.get(key)
            if existing is None and t.metatable is not None:
                newidx = t.metatable.get("__newindex")
                if newidx is not None:
                    if isinstance(newidx, LuaTable):
                        self.table_set(newidx, key, value, line)
                        return
                    self.call(newidx, [t, key, value], line)
                    return
            t.rawset(key, value)
            return
        if t is None:
            raise LuaError(self._rt_err(f"attempt to index a nil value", line))
        raise LuaError(self._rt_err(f"attempt to index a {lua_type(t)} value", line))

    # ---- Execution ----

    def exec_chunk(self, ast, env, varargs=None):
        # chunk = Node("chunk", line, block)
        try:
            self.exec_block(ast.children[0], env, varargs)
        except ReturnException as r:
            return r.values
        return []

    def exec_block(self, block_node, env, varargs=None):
        stmts = block_node.children[0]
        i = 0
        while i < len(stmts):
            s = stmts[i]
            try:
                self.exec_stmt(s, env, varargs)
                i += 1
            except GotoException as g:
                # find label in current block
                found = None
                for j, st in enumerate(stmts):
                    if st.type == "label" and st.children[0] == g.label:
                        found = j
                        break
                if found is None:
                    raise
                i = found + 1

    def exec_stmt(self, node, env, varargs):
        t = node.type
        if t == "assign":
            lhs_nodes, rhs_nodes = node.children
            values = self.eval_exprlist(rhs_nodes, env, varargs, len(lhs_nodes))
            # Evaluate LHS targets first (lua evaluates lhs before rhs but for simplicity we do this order)
            for i, tgt in enumerate(lhs_nodes):
                val = values[i] if i < len(values) else None
                self.assign_target(tgt, val, env, varargs)
        elif t == "local":
            names, exprs = node.children
            vals = self.eval_exprlist(exprs, env, varargs, len(names)) if exprs else []
            for i, n in enumerate(names):
                env.declare_local(n, vals[i] if i < len(vals) else None)
        elif t == "localfunction":
            name, func_node = node.children
            env.declare_local(name, None)  # allow recursion
            fn = self.eval_expr(func_node, env, varargs)
            if isinstance(fn, LuaFunction):
                fn.name = name
            env.vars[name] = fn
        elif t == "exprstmt":
            self.eval_expr(node.children[0], env, varargs)
        elif t == "if":
            cond, then_body, elifs, else_body = node.children
            if is_truthy(self.eval_expr(cond, env, varargs)):
                self.exec_block(then_body, Environment(env), varargs)
            else:
                matched = False
                for econd, ebody, _el in elifs:
                    if is_truthy(self.eval_expr(econd, env, varargs)):
                        self.exec_block(ebody, Environment(env), varargs)
                        matched = True
                        break
                if not matched and else_body is not None:
                    self.exec_block(else_body, Environment(env), varargs)
        elif t == "while":
            cond, body = node.children
            while is_truthy(self.eval_expr(cond, env, varargs)):
                try:
                    self.exec_block(body, Environment(env), varargs)
                except BreakException:
                    return
        elif t == "repeat":
            body, cond = node.children
            while True:
                loop_env = Environment(env)
                try:
                    self.exec_block(body, loop_env, varargs)
                except BreakException:
                    return
                if is_truthy(self.eval_expr(cond, loop_env, varargs)):
                    break
        elif t == "fornum":
            name, start_e, stop_e, step_e, body = node.children
            start = lua_tonumber(self.eval_expr(start_e, env, varargs))
            stop = lua_tonumber(self.eval_expr(stop_e, env, varargs))
            step = lua_tonumber(self.eval_expr(step_e, env, varargs)) if step_e is not None else 1
            if start is None or stop is None or step is None:
                raise LuaError(self._rt_err("'for' initial value must be a number", node.line))
            i = start
            while (step > 0 and i <= stop) or (step < 0 and i >= stop):
                loop_env = Environment(env)
                loop_env.declare_local(name, i)
                try:
                    self.exec_block(body, loop_env, varargs)
                except BreakException:
                    return
                i = i + step
        elif t == "forin":
            names, exprs, body = node.children
            vals = self.eval_exprlist(exprs, env, varargs, 3)
            while len(vals) < 3:
                vals.append(None)
            f, s, var = vals[0], vals[1], vals[2]
            while True:
                result = self.call(f, [s, var], node.line)
                if not result or result[0] is None:
                    break
                var = result[0]
                loop_env = Environment(env)
                for i, n in enumerate(names):
                    loop_env.declare_local(n, result[i] if i < len(result) else None)
                try:
                    self.exec_block(body, loop_env, varargs)
                except BreakException:
                    return
        elif t == "do":
            self.exec_block(node.children[0], Environment(env), varargs)
        elif t == "break":
            raise BreakException()
        elif t == "return":
            exprs = node.children[0]
            vals = self.eval_exprlist(exprs, env, varargs, -1)
            raise ReturnException(vals)
        elif t == "label":
            pass
        elif t == "goto":
            raise GotoException(node.children[0])
        else:
            raise LuaError(f"unknown stmt {t}")

    def assign_target(self, tgt, value, env, varargs):
        if tgt.type == "name":
            name = tgt.children[0]
            found, _ = env.get_local(name)
            if found:
                env.set_local(name, value)
            else:
                self.globals.rawset(name, value)
        elif tgt.type == "index":
            obj = self.eval_expr(tgt.children[0], env, varargs)
            key = self.eval_expr(tgt.children[1], env, varargs)
            self.table_set(obj, key, value, tgt.line)
        else:
            raise LuaError("bad assign target")

    def eval_exprlist(self, exprs, env, varargs, want):
        """Evaluate expression list. If want==-1 or want == len(exprs), last expr is expanded."""
        results = []
        if not exprs:
            return results
        for i, e in enumerate(exprs):
            if i == len(exprs) - 1:
                # last expression - expand if multi-return
                vals = self.eval_expr_multi(e, env, varargs)
                results.extend(vals)
            else:
                results.append(self.eval_expr(e, env, varargs))
        return results

    def eval_expr(self, node, env, varargs):
        """Evaluate and return single value (first of multi)."""
        vals = self.eval_expr_multi(node, env, varargs)
        return vals[0] if vals else None

    def eval_expr_multi(self, node, env, varargs):
        t = node.type
        if t == "number":
            return [node.children[0]]
        if t == "string":
            return [node.children[0]]
        if t == "bool":
            return [node.children[0]]
        if t == "nil":
            return [None]
        if t == "vararg":
            return list(varargs) if varargs is not None else []
        if t == "name":
            name = node.children[0]
            found, v = env.get_local(name)
            if found:
                return [v]
            return [self.globals.get(name)]
        if t == "paren":
            return [self.eval_expr(node.children[0], env, varargs)]
        if t == "index":
            obj = self.eval_expr(node.children[0], env, varargs)
            key = self.eval_expr(node.children[1], env, varargs)
            return [self.table_get(obj, key, node.line)]
        if t == "unop":
            op = node.children[0]
            v = self.eval_expr(node.children[1], env, varargs)
            if op == "-":
                n = lua_tonumber(v) if not isinstance(v, bool) else None
                if n is None:
                    raise LuaError(self._rt_err(f"attempt to perform arithmetic on a {lua_type(v)} value", node.line))
                return [-n]
            if op == "not":
                return [not is_truthy(v)]
            if op == "#":
                return [self.length(v, node.line)]
        if t == "binop":
            op = node.children[0]
            if op == "and":
                a = self.eval_expr(node.children[1], env, varargs)
                if not is_truthy(a):
                    return [a]
                return [self.eval_expr(node.children[2], env, varargs)]
            if op == "or":
                a = self.eval_expr(node.children[1], env, varargs)
                if is_truthy(a):
                    return [a]
                return [self.eval_expr(node.children[2], env, varargs)]
            a = self.eval_expr(node.children[1], env, varargs)
            b = self.eval_expr(node.children[2], env, varargs)
            if op in ("+", "-", "*", "/", "%", "^"):
                return [self.arith(op, a, b, node.line)]
            if op == "..":
                return [self.concat(a, b, node.line)]
            if op in ("==", "~=", "<", "<=", ">", ">="):
                return [self.compare(op, a, b, node.line)]
        if t == "table":
            return [self.eval_table(node, env, varargs)]
        if t == "function":
            params, vararg, body = node.children
            return [LuaFunction(params, vararg, body, env)]
        if t == "call":
            fn_node, arg_nodes = node.children
            fn = self.eval_expr(fn_node, env, varargs)
            args = self.eval_exprlist(arg_nodes, env, varargs, -1)
            return self.call(fn, args, node.line)
        if t == "mcall":
            obj_node, mname, arg_nodes = node.children
            obj = self.eval_expr(obj_node, env, varargs)
            fn = self.table_get(obj, mname, node.line)
            args = [obj] + self.eval_exprlist(arg_nodes, env, varargs, -1)
            return self.call(fn, args, node.line)
        raise LuaError(f"unknown expr {t}")

    def eval_table(self, node, env, varargs):
        t = LuaTable()
        fields = node.children[0]
        idx = 1
        last = len(fields) - 1
        for i, (kind, k, v) in enumerate(fields):
            if kind == "kv":
                key = self.eval_expr(k, env, varargs)
                val = self.eval_expr(v, env, varargs)
                t.rawset(key, val)
            else:
                if i == last:
                    vals = self.eval_expr_multi(v, env, varargs)
                    for x in vals:
                        t.rawset(idx, x)
                        idx += 1
                else:
                    val = self.eval_expr(v, env, varargs)
                    t.rawset(idx, val)
                    idx += 1
        return t

    def call(self, fn, args, line):
        if fn is None:
            raise LuaError(self._rt_err("attempt to call a nil value", line))
        if isinstance(fn, BuiltinFunction):
            try:
                r = fn.fn(args)
            except LuaError:
                raise
            except Exception as e:
                raise LuaError(self._rt_err(str(e), line))
            if r is None:
                return []
            if isinstance(r, list):
                return r
            return [r]
        if isinstance(fn, LuaFunction):
            call_env = Environment(fn.env)
            for i, p in enumerate(fn.params):
                call_env.declare_local(p, args[i] if i < len(args) else None)
            vararg_vals = args[len(fn.params):] if fn.is_vararg else []
            try:
                self.exec_block(fn.body, call_env, vararg_vals)
            except ReturnException as r:
                return r.values
            return []
        if isinstance(fn, LuaTable):
            # __call
            if fn.metatable is not None:
                cm = fn.metatable.get("__call")
                if cm is not None:
                    return self.call(cm, [fn] + list(args), line)
        raise LuaError(self._rt_err(f"attempt to call a {lua_type(fn)} value", line))
