"""Lua standard library (minimal)."""

import sys
import math
import random
import os
import re
import time

from values import (
    LuaError, LuaTable, LuaFunction, BuiltinFunction,
    lua_type, is_truthy, lua_tostring, lua_tonumber,
)


def _bf(name, fn):
    return BuiltinFunction(fn, name)


def make_stdlib(interp):
    """Create and return globals table populated with stdlib."""
    G = LuaTable()

    def b_print(args):
        parts = []
        for a in args:
            parts.append(_tostring(a))
        sys.stdout.write("\t".join(parts) + "\n")
        return []

    def _tostring(v):
        if isinstance(v, LuaTable) and v.metatable is not None:
            mm = v.metatable.get("__tostring")
            if mm is not None:
                r = interp.call(mm, [v], 0)
                return r[0] if r else ""
        return lua_tostring(v)

    def b_tostring(args):
        return [_tostring(args[0] if args else None)]

    def b_tonumber(args):
        v = args[0] if args else None
        base = args[1] if len(args) > 1 else None
        return [lua_tonumber(v, base)]

    def b_type(args):
        return [lua_type(args[0] if args else None)]

    def b_ipairs(args):
        t = args[0]
        def iterfn(a):
            tb, i = a[0], a[1]
            ni = i + 1
            v = tb.get(ni) if isinstance(tb, LuaTable) else None
            if v is None:
                return [None]
            return [ni, v]
        return [BuiltinFunction(iterfn, "ipairs_iter"), t, 0]

    def b_pairs(args):
        t = args[0]
        if isinstance(t, LuaTable) and t.metatable is not None:
            mm = t.metatable.get("__pairs")
            if mm is not None:
                return interp.call(mm, [t], 0)
        # build iterator capturing items
        items = list(t.iter_pairs()) if isinstance(t, LuaTable) else []
        it = iter(items)
        state = {"next": it}
        def nextfn(a):
            try:
                k, v = next(state["next"])
                return [k, v]
            except StopIteration:
                return [None]
        return [BuiltinFunction(nextfn, "pairs_iter"), t, None]

    def b_next(args):
        t = args[0]
        k = args[1] if len(args) > 1 else None
        if not isinstance(t, LuaTable):
            raise LuaError("bad argument #1 to 'next' (table expected)")
        items = list(t.iter_pairs())
        if k is None:
            if items:
                return [items[0][0], items[0][1]]
            return [None]
        for i, (ik, iv) in enumerate(items):
            if ik == k:
                if i + 1 < len(items):
                    return [items[i+1][0], items[i+1][1]]
                return [None]
        return [None]

    def b_select(args):
        if not args:
            raise LuaError("bad argument #1 to 'select'")
        n = args[0]
        rest = args[1:]
        if n == "#":
            return [len(rest)]
        i = lua_tonumber(n)
        if i is None:
            raise LuaError("bad argument #1 to 'select'")
        i = int(i)
        if i < 0:
            i = len(rest) + i + 1
        if i < 1:
            raise LuaError("bad argument #1 to 'select' (index out of range)")
        return list(rest[i-1:])

    def b_error(args):
