        k = args[1] if len(args) > 1 else None
        if not isinstance(t, LuaTable):
            raise LuaError("bad argument #1 to 'next' (table expected)")
        items = list(t.iter_pairs())
        if k is None:
            if items:
                return [items[0][0], items[0][1]]
            return [None]
        for i, (ik, iv) in enumerate(items):
            if ik == k:
                if i + 1 < len(items):
                    return [items[i+1][0], items[i+1][1]]
                return [None]
        return [None]

    def b_select(args):
        if not args:
            raise LuaError("bad argument #1 to 'select'")
        n = args[0]
        rest = args[1:]
        if n == "#":
            return [len(rest)]
        i = lua_tonumber(n)
        if i is None:
            raise LuaError("bad argument #1 to 'select'")
        i = int(i)
        if i < 0:
            i = len(rest) + i + 1
        if i < 1:
            raise LuaError("bad argument #1 to 'select' (index out of range)")
        return list(rest[i-1:])

