        fn = args[0]
        fargs = args[1:]
        try:
            r = interp.call(fn, list(fargs), 0)
            return [True] + list(r)
        except LuaError as e:
            return [False, e.value]
        except Exception as e:
            return [False, str(e)]

    def b_xpcall(args):
        if len(args) < 2:
            raise LuaError("bad argument to 'xpcall'")
        fn = args[0]
        handler = args[1]
        fargs = args[2:]
        try:
            r = interp.call(fn, list(fargs), 0)
            return [True] + list(r)
        except LuaError as e:
            try:
                hr = interp.call(handler, [e.value], 0)
                return [False] + list(hr)
            except LuaError as e2:
                return [False, e2.value]

