    def t_insert(a):
        t = a[0]
        if len(a) == 2:
            t.rawset(t.length()+1, a[1])
        else:
            pos = int(a[1]); val = a[2]
            n = t.length()
            for i in range(n, pos-1, -1):
                t.rawset(i+1, t.get(i))
            t.rawset(pos, val)
        return []

    def t_remove(a):
        t = a[0]
        n = t.length()
        pos = int(a[1]) if len(a) > 1 and a[1] is not None else n
        if n == 0:
            return [None]
        v = t.get(pos)
        for i in range(pos, n):
            t.rawset(i, t.get(i+1))
        t.rawset(n, None)
        return [v]

    def t_concat(a):
        t = a[0]
        sep = a[1] if len(a) > 1 and a[1] is not None else ""
        i = int(a[2]) if len(a) > 2 and a[2] is not None else 1
        j = int(a[3]) if len(a) > 3 and a[3] is not None else t.length()
        parts = []
        for k in range(i, j+1):
            v = t.get(k)
            parts.append(_tostring(v))
        return [sep.join(parts)]

    def t_sort(a):
        t = a[0]
        comp = a[1] if len(a) > 1 else None
        items = []
        for i in range(1, t.length()+1):
            items.append(t.get(i))
        import functools
        if comp is not None:
            def cmp(x, y):
                r = interp.call(comp, [x, y], 0)
                lt = is_truthy(r[0]) if r else False
                if lt: return -1
                r2 = interp.call(comp, [y, x], 0)
                lt2 = is_truthy(r2[0]) if r2 else False
                if lt2: return 1
                return 0
            items.sort(key=functools.cmp_to_key(cmp))
        else:
            items.sort(key=lambda x: (0 if isinstance(x, (int,float)) else 1, x))
        for i, v in enumerate(items, 1):
            t.rawset(i, v)
        return []

    def t_unpack(a):
        return b_unpack(a)

