    def io_read(a):
        fmt = a[0] if a else "*l"
        if fmt in ("*l", "l", "*L", "L", None):
            line = sys.stdin.readline()
            if not line:
                return [None]
            if fmt in ("*l", "l", None):
                return [line.rstrip("\n")]
            return [line]
        if fmt in ("*a", "a"):
            return [sys.stdin.read()]
        if fmt in ("*n", "n"):
            line = sys.stdin.readline()
            try:
                return [float(line.strip())]
