# ---- Lua pattern matching ----

class LuaPattern:
    """Implementation of Lua string pattern matching."""
    def __init__(self, pattern):
        self.pat = pattern

    def find(self, s, init):
        """Try to find a match starting at position >= init. Returns (start, end, captures) or None."""
        p = self.pat
        anchor = len(p) > 0 and p[0] == "^"
        pstart = 1 if anchor else 0
        start = init
        while start <= len(s):
            captures = []
            res = self._match(s, start, p, pstart, captures)
            if res is not None:
                caps = []
                for c in captures:
                    if c[2] == "pos":
                        caps.append(c[0] + 1)
                    else:
                        caps.append(s[c[0]:c[1]])
                return (start, res, caps)
            if anchor:
                return None
            start += 1
        return None

    def _single_match(self, c, p, pi):
        if pi >= len(p):
            return False
        pc = p[pi]
        if pc == ".":
            return True
        if pc == "%":
            return self._match_class(c, p[pi+1]) if pi+1 < len(p) else False
        if pc == "[":
            return self._match_set(c, p, pi)
        return pc == c

    def _match_class(self, c, cl):
        if cl == "a": return c.isalpha()
        if cl == "A": return not c.isalpha()
        if cl == "d": return c.isdigit()
        if cl == "D": return not c.isdigit()
        if cl == "l": return c.islower()
        if cl == "L": return not c.islower()
        if cl == "u": return c.isupper()
        if cl == "U": return not c.isupper()
        if cl == "s": return c in " \t\n\r\v\f"
        if cl == "S": return c not in " \t\n\r\v\f"
        if cl == "w": return c.isalnum()
        if cl == "W": return not c.isalnum()
        if cl == "p": return not c.isalnum() and not c.isspace() and c.isprintable()
        if cl == "P": return not (not c.isalnum() and not c.isspace() and c.isprintable())
        if cl == "c": return not c.isprintable() or c in "\t\n\r\v\f"
        if cl == "x": return c in "0123456789abcdefABCDEF"
        return c == cl

    def _match_set(self, c, p, pi):
        # p[pi] == '['
        end = pi + 1
        negate = False
        if end < len(p) and p[end] == "^":
            negate = True
            end += 1
        # find matching ]
        start = end
        first = True
        while end < len(p) and (first or p[end] != "]"):
            first = False
            if p[end] == "%" and end+1 < len(p):
                end += 2
            else:
                end += 1
        # now p[start:end] is set content
        i = start
        matched = False
        while i < end:
            if p[i] == "%" and i+1 < end:
                if self._match_class(c, p[i+1]):
                    matched = True
                i += 2
            elif i+2 < end and p[i+1] == "-":
                if p[i] <= c <= p[i+2]:
                    matched = True
                i += 3
            else:
                if p[i] == c:
                    matched = True
                i += 1
        return matched != negate

    def _pattern_end(self, p, pi):
        """Return index just after the single pattern unit at pi."""
        if pi >= len(p):
            return pi
        c = p[pi]
        if c == "%":
            return pi + 2
        if c == "[":
            e = pi + 1
            if e < len(p) and p[e] == "^":
                e += 1
            first = True
            while e < len(p) and (first or p[e] != "]"):
                first = False
                if p[e] == "%" and e+1 < len(p):
                    e += 2
                else:
                    e += 1
            return e + 1
        return pi + 1

    def _match(self, s, si, p, pi, captures):
        while pi < len(p):
            # Handle captures
            if p[pi] == "(":
                if pi+1 < len(p) and p[pi+1] == ")":
                    # position capture
                    captures.append([si, si, "pos"])
                    r = self._match(s, si, p, pi+2, captures)
                    if r is not None:
                        return r
                    captures.pop()
                    return None
                captures.append([si, -1, "str"])
                r = self._match(s, si, p, pi+1, captures)
                if r is not None:
                    return r
                captures.pop()
                return None
            if p[pi] == ")":
                # close most recent open
                for i in range(len(captures)-1, -1, -1):
                    if captures[i][1] == -1:
                        captures[i][1] = si
                        r = self._match(s, si, p, pi+1, captures)
                        if r is not None:
                            return r
                        captures[i][1] = -1
                        return None
                return None
            if p[pi] == "$" and pi == len(p) - 1:
                if si == len(s):
                    return si
                return None
            # Handle %N backreference
            if p[pi] == "%" and pi+1 < len(p) and p[pi+1].isdigit() and p[pi+1] != "0":
                n = int(p[pi+1]) - 1
                if n >= len(captures):
                    return None
                cap = captures[n]
                capstr = s[cap[0]:cap[1]]
                if s[si:si+len(capstr)] == capstr:
                    pi += 2
                    si += len(capstr)
                    continue
                return None
            # single match unit
            pe = self._pattern_end(p, pi)
            has_quant = pe < len(p) and p[pe] in "*+-?"
            if has_quant:
                q = p[pe]
                if q == "?":
                    if si < len(s) and self._single_match(s[si], p, pi):
                        r = self._match(s, si+1, p, pe+1, captures)
                        if r is not None:
                            return r
                    return self._match(s, si, p, pe+1, captures)
                if q == "+":
                    if si < len(s) and self._single_match(s[si], p, pi):
                        return self._match_greedy(s, si+1, p, pi, pe, captures)
                    return None
                if q == "*":
                    return self._match_greedy(s, si, p, pi, pe, captures)
                if q == "-":
                    return self._match_lazy(s, si, p, pi, pe, captures)
            else:
                if si < len(s) and self._single_match(s[si], p, pi):
                    si += 1
                    pi = pe
                    continue
                return None
        return si

    def _match_greedy(self, s, si, p, pi, pe, captures):
        count = 0
        while si + count < len(s) and self._single_match(s[si+count], p, pi):
            count += 1
        while count >= 0:
            r = self._match(s, si+count, p, pe+1, captures)
            if r is not None:
                return r
            count -= 1
        return None

    def _match_lazy(self, s, si, p, pi, pe, captures):
        while True:
            r = self._match(s, si, p, pe+1, captures)
            if r is not None:
                return r
            if si < len(s) and self._single_match(s[si], p, pi):
                si += 1
            else:
                return None
