        return []

    def _tostring(v):
        if isinstance(v, LuaTable) and v.metatable is not None:
            mm = v.metatable.get("__tostring")
            if mm is not None:
                r = interp.call(mm, [v], 0)
                return r[0] if r else ""
        return lua_tostring(v)

    def b_tostring(args):
        return [_tostring(args[0] if args else None)]

    def b_tonumber(args):
        v = args[0] if args else None
        base = args[1] if len(args) > 1 else None
        return [lua_tonumber(v, base)]

