        t = args[0]
        def iterfn(a):
            tb, i = a[0], a[1]
            ni = i + 1
            v = tb.get(ni) if isinstance(tb, LuaTable) else None
            if v is None:
                return [None]
            return [ni, v]
        return [BuiltinFunction(iterfn, "ipairs_iter"), t, 0]

