        t = args[0]
        if isinstance(t, LuaTable) and t.metatable is not None:
            mm = t.metatable.get("__pairs")
            if mm is not None:
                return interp.call(mm, [t], 0)
        # build iterator capturing items
        items = list(t.iter_pairs()) if isinstance(t, LuaTable) else []
        it = iter(items)
        state = {"next": it}
        def nextfn(a):
            try:
                k, v = next(state["next"])
                return [k, v]
            except StopIteration:
                return [None]
        return [BuiltinFunction(nextfn, "pairs_iter"), t, None]

    def b_next(args):
