    def s_format(a):
        fmt = a[0]
        args = list(a[1:])
        out = []
        i = 0
        argi = 0
        while i < len(fmt):
            c = fmt[i]
            if c != "%":
                out.append(c)
                i += 1
                continue
            # parse directive
            i += 1
            if i < len(fmt) and fmt[i] == "%":
                out.append("%")
                i += 1
                continue
            spec = "%"
            # flags
            while i < len(fmt) and fmt[i] in "-+ #0":
                spec += fmt[i]
                i += 1
            while i < len(fmt) and fmt[i].isdigit():
                spec += fmt[i]; i += 1
            if i < len(fmt) and fmt[i] == ".":
                spec += "."; i += 1
                while i < len(fmt) and fmt[i].isdigit():
                    spec += fmt[i]; i += 1
            if i >= len(fmt):
                raise LuaError("invalid option to 'format'")
            conv = fmt[i]
            i += 1
            if argi >= len(args):
                raise LuaError("bad argument to 'format' (no value)")
            v = args[argi]; argi += 1
            if conv in ("d", "i"):
                n = lua_tonumber(v)
                if n is None: raise LuaError("bad argument to 'format'")
                out.append(spec + "d" % int(n) if False else (spec + "d") % int(n))
            elif conv in ("u",):
                n = lua_tonumber(v)
                out.append((spec + "d") % int(n))
            elif conv in ("o", "x", "X"):
                n = lua_tonumber(v)
                out.append((spec + conv) % int(n))
            elif conv in ("e", "E", "f", "g", "G"):
                n = lua_tonumber(v)
                out.append((spec + conv) % float(n))
            elif conv == "c":
                n = lua_tonumber(v)
                out.append(chr(int(n)))
            elif conv == "s":
                s = _tostring(v) if not isinstance(v, str) else v
                out.append((spec + "s") % s)
            elif conv == "q":
                s = v if isinstance(v, str) else _tostring(v)
                out.append('"' + s.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n").replace("\r", "\\r").replace("\0", "\\0") + '"')
            else:
                raise LuaError(f"invalid option '%{conv}' to 'format'")
        return ["".join(out)]

