    def s_find(a):
        s = a[0]
        pat = a[1]
        init = int(a[2]) if len(a) > 2 and a[2] is not None else 1
        plain = is_truthy(a[3]) if len(a) > 3 else False
        L = len(s)
        if init < 0: init = max(L + init + 1, 1)
        if init < 1: init = 1
        if plain:
            idx = s.find(pat, init-1)
            if idx < 0: return [None]
            return [idx+1, idx+len(pat)]
        p = LuaPattern(pat)
        m = p.find(s, init-1)
        if m is None:
            return [None]
        start, end, captures = m
        return [start+1, end] + captures

    def s_match(a):
        s = a[0]
        pat = a[1]
        init = int(a[2]) if len(a) > 2 and a[2] is not None else 1
        L = len(s)
        if init < 0: init = max(L + init + 1, 1)
        if init < 1: init = 1
        p = LuaPattern(pat)
        m = p.find(s, init-1)
        if m is None:
            return [None]
        start, end, captures = m
        if captures:
            return captures
        return [s[start:end]]

    def s_gmatch(a):
        s = a[0]
        pat = a[1]
        p = LuaPattern(pat)
        state = {"pos": 0}
        def iterfn(_a):
            while state["pos"] <= len(s):
                m = p.find(s, state["pos"])
                if m is None:
                    return [None]
                start, end, captures = m
                if end == start:
                    state["pos"] = end + 1
                else:
                    state["pos"] = end
                if captures:
                    return captures
                return [s[start:end]]
            return [None]
        return [BuiltinFunction(iterfn, "gmatch_iter")]

    def s_gsub(a):
        s = a[0]
        pat = a[1]
        repl = a[2]
        max_n = int(a[3]) if len(a) > 3 and a[3] is not None else -1
        p = LuaPattern(pat)
        out = []
        pos = 0
        count = 0
        while pos <= len(s) and (max_n < 0 or count < max_n):
            m = p.find(s, pos)
            if m is None:
                break
            start, end, captures = m
            out.append(s[pos:start])
            matched = s[start:end]
            if isinstance(repl, str):
                r = []
                i = 0
                while i < len(repl):
                    c = repl[i]
                    if c == "%" and i+1 < len(repl):
                        nxt = repl[i+1]
                        if nxt == "%":
                            r.append("%")
                        elif nxt == "0":
                            r.append(matched)
                        elif nxt.isdigit():
                            n = int(nxt)
                            if n <= len(captures):
                                r.append(_tostring(captures[n-1]))
                        else:
                            r.append(nxt)
                        i += 2
                    else:
                        r.append(c); i += 1
                out.append("".join(r))
            elif isinstance(repl, LuaTable):
                k = captures[0] if captures else matched
                v = repl.get(k)
                if v is None or v is False:
                    out.append(matched)
                else:
                    out.append(_tostring(v))
            elif isinstance(repl, (BuiltinFunction, LuaFunction)):
                cargs = captures if captures else [matched]
                rv = interp.call(repl, cargs, 0)
                rr = rv[0] if rv else None
                if rr is None or rr is False:
                    out.append(matched)
                else:
                    out.append(_tostring(rr))
            count += 1
            if end == start:
                if pos < len(s):
                    out.append(s[pos])
                pos += 1
            else:
                pos = end
        out.append(s[pos:])
        return ["".join(out), count]

