# ---- Lua pattern matching ----

class LuaPattern:
    """Implementation of Lua string pattern matching."""
    def __init__(self, pattern):
        self.pat = pattern

    def find(self, s, init):
        """Try to find a match starting at position >= init. Returns (start, end, captures) or None."""
        p = self.pat
        anchor = len(p) > 0 and p[0] == "^"
        pstart = 1 if anchor else 0
        start = init
        while start <= len(s):
            captures = []
            res = self._match(s, start, p, pstart, captures)
            if res is not None:
                caps = []
                for c in captures:
                    if c[2] == "pos":
                        caps.append(c[0] + 1)
                    else:
                        caps.append(s[c[0]:c[1]])
                return (start, res, caps)
            if anchor:
                return None
            start += 1
        return None

    def _single_match(self, c, p, pi):
        if pi >= len(p):
            return False
        pc = p[pi]
        if pc == ".":
            return True
        if pc == "%":
            return self._match_class(c, p[pi+1]) if pi+1 < len(p) else False
        if pc == "[":
            return self._match_set(c, p, pi)
        return pc == c

    def _match_class(self, c, cl):
        if cl == "a": return c.isalpha()
        if cl == "A": return not c.isalpha()
        if cl == "d": return c.isdigit()
        if cl == "D": return not c.isdigit()
        if cl == "l": return c.islower()
        if cl == "L": return not c.islower()
        if cl == "u": return c.isupper()
        if cl == "U": return not c.isupper()
        if cl == "s": return c in " \t\n\r\v\f"
        if cl == "S": return c not in " \t\n\r\v\f"
        if cl == "w": return c.isalnum()
        if cl == "W": return not c.isalnum()
        if cl == "p": return not c.isalnum() and not c.isspace() and c.isprintable()
        if cl == "P": return not (not c.isalnum() and not c.isspace() and c.isprintable())
        if cl == "c": return not c.isprintable() or c in "\t\n\r\v\f"
        if cl == "x": return c in "0123456789abcdefABCDEF"
        return c == cl

    def _match_set(self, c, p, pi):
